\draw (0,0) rectangle (2,1.5);
\node[left] at (0,0.75) {$3\,\mathrm{m}$};
\node[below] at (1,-0.3) {Front / Back};
\draw (3.2,0) rectangle (6.2,1.5);
\node[above] at (4.7,1.5) {$6\,\mathrm{m}$};
\node[below] at (4.7,-0.3) {Side};
\draw (7.4,0) rectangle (9.4,3);
\node[above] at (8.4,3) {$4\,\mathrm{m}$};
\node[below] at (8.4,-0.3) {Top};
\end{tikzpicture}
[/tikz]

mastery.solution_text:
The rectangular prism is $4\,\mathrm{m}$ wide, $3\,\mathrm{m}$ high and $6\,\mathrm{m}$ deep. Label these three directions on the sketch.
[tikz]
\begin{tikzpicture}[every node/.style={font=\small}]
\draw (0,0) rectangle (2,1.5);
\draw (2,0)--(3.8,1.2)--(3.8,2.7)--(2,1.5);
\draw (0,1.5)--(1.8,2.7)--(3.8,2.7);
\draw[dashed] (0,0)--(1.8,1.2)--(3.8,1.2) (1.8,1.2)--(1.8,2.7);
\node[below] at (1,0) {$4\,\mathrm{m}$};
\node[left] at (0,0.75) {$3\,\mathrm{m}$};
\node[below right] at (2.9,0.6) {$6\,\mathrm{m}$};
\end{tikzpicture}
[/tikz]
